from __future__ import annotations

from typing import Tuple

import torch
import torch.distributed as dist
from torch.utils.data import DataLoader, Dataset, DistributedSampler


class StreamingDistributedSampler(DistributedSampler):
    """Non-shuffling distributed sampler whose indices are generated by stride.

    PyTorch's regular non-shuffling sampler materializes ``list(range(N))``.
    Stress workloads can have very large synthetic datasets, so this override
    keeps only a small ``range`` object in memory and resolves the real rank
    after Lightning has initialized the process group.
    """

    def __iter__(self):  # noqa: ANN204
        if not dist.is_available() or not dist.is_initialized():
            raise RuntimeError("Distributed sampling requires an initialized process group")
        actual_world = dist.get_world_size()
        actual_rank = dist.get_rank()
        if actual_world != self.num_replicas:
            raise RuntimeError(
                f"Configured {self.num_replicas} replicas, but process group has {actual_world}"
            )
        if actual_rank < 0 or actual_rank >= self.num_replicas:
            raise RuntimeError(f"Invalid distributed rank {actual_rank} for {self.num_replicas} replicas")
        if len(self.dataset) % self.num_replicas:
            raise RuntimeError("Dataset length must be divisible by distributed replicas")
        return iter(range(actual_rank, len(self.dataset), self.num_replicas))

    def __len__(self) -> int:
        return len(self.dataset) // self.num_replicas


class RandomDataset(Dataset):
    def __init__(self, length: int, input_dim: int, output_dim: int) -> None:
        self.length = length
        self.input_dim = input_dim
        self.output_dim = output_dim

    def __len__(self) -> int:
        return self.length

    def __getitem__(self, idx: int) -> Tuple[torch.Tensor, torch.Tensor]:  # noqa: ARG002
        x = torch.randn(self.input_dim)
        y = torch.randn(self.output_dim)
        return x, y


class DummyBatchDataset(Dataset):
    """Lightweight dataset used when data is generated on-device."""

    def __init__(self, length: int) -> None:
        self.length = length

    def __len__(self) -> int:
        return self.length

    def __getitem__(self, idx: int):  # noqa: D401, ANN001
        return 0


def build_dataloader(
    dataset_size: int,
    batch_size: int,
    input_dim: int,
    output_dim: int,
    num_workers: int = 4,
    generate_on_device: bool = False,
    pin_memory: bool = False,
    distributed_replicas: int = 1,
) -> DataLoader:
    for name, value in {
        "dataset_size": dataset_size,
        "batch_size": batch_size,
        "input_dim": input_dim,
        "output_dim": output_dim,
        "num_workers": num_workers,
    }.items():
        if isinstance(value, bool) or not isinstance(value, int) or value < 0 or (name != "num_workers" and value <= 0):
            raise ValueError(f"{name} must be a non-negative integer (positive for dimensions/sizes)")
    if not isinstance(generate_on_device, bool) or not isinstance(pin_memory, bool):
        raise ValueError("generate_on_device and pin_memory must be booleans")
    if isinstance(distributed_replicas, bool) or not isinstance(distributed_replicas, int) or distributed_replicas < 1:
        raise ValueError("distributed_replicas must be a positive integer")
    if distributed_replicas > 1 and dataset_size % distributed_replicas:
        raise ValueError("dataset_size must be divisible by distributed_replicas")
    dataset = DummyBatchDataset(dataset_size) if generate_on_device else RandomDataset(dataset_size, input_dim, output_dim)
    workers = 0 if generate_on_device else num_workers
    sampler = (
        StreamingDistributedSampler(
            dataset,
            num_replicas=distributed_replicas,
            rank=0,
            shuffle=False,
            drop_last=True,
        )
        if distributed_replicas > 1
        else None
    )
    kwargs = {
        "dataset": dataset,
        "batch_size": batch_size,
        # Samples are freshly generated, so shuffling adds overhead without
        # changing the distribution.  A full batch is required on every rank.
        "shuffle": False,
        "drop_last": True,
        "num_workers": workers,
        "pin_memory": pin_memory and not generate_on_device,
        "persistent_workers": workers > 0,
    }
    if sampler is not None:
        kwargs["sampler"] = sampler
    if workers > 0:
        kwargs["prefetch_factor"] = 2
    return DataLoader(**kwargs)
